#!/usr/bin/env python3
"""Validate collected observations and render the Italian result report."""
import argparse,hashlib,itertools,json,pathlib
p=argparse.ArgumentParser();p.add_argument('--evidence',required=True);p.add_argument('--report',required=True);p.add_argument('--summary',required=True);a=p.parse_args()
root=pathlib.Path(a.evidence);final=root/'final2';data=json.loads((final/'summary.json').read_text());assert data['ok']
rows=data['results'];expected={(n,r,policy) for n,r,policy in itertools.product([100,500,1000,2000,5000],[1,3],['all-oldest','all-newest','cap500-oldest','cap500-newest'])}
main=[x for x in rows if not x['policy'].endswith('unobserved')];assert len(main)==40;assert {(x['n'],x['relays'],x['policy']) for x in main}==expected;assert len(rows)==41
checks=[];per_id={}
for row in main:
 d=json.loads((final/(row['name']+'.json')).read_text());s=d['stats'];validated={x['seq'] for x in s['validated']};missing=[x for x in s['frames'] if x['seq'] not in validated]
 assert len(s['frames'])==len(s['wire'])==row['frames']
 assert len(missing)==row['droppedFrames'];assert len(s['frames'])==len(validated)+len(missing)
 assert all(x['seq'] in range(len(s['frames'])) for x in s['validated'])
 assert row['newCopies']==len([x for x in s['messages'] if x['id']=='new-'+row['name']])
 assert row['delivered']==bool(row['newCopies'])
 assert len(s['requests'])>=row['relays']*2
 assert all('since' not in x['filter'] and 'limit' not in x['filter'] for x in s['requests'][:row['relays']])
 assert any('since' in x['filter'] for x in s['requests'][row['relays']:])
 # More than a second between the last validation and snapshot: not an unfinished
 # queue mistaken for a drop. The socket frame seq uniquely identifies copies.
 assert s['elapsedMs']-max(x['ms'] for x in s['validated'])>1000
 ids={}
 for frame in s['frames']:
  entry=ids.setdefault(frame['id'],{'new':frame['id']==row['newId'],'received':0,'validated':0,'dropped':0});entry['received']+=1;entry['validated' if frame['seq'] in validated else 'dropped']+=1
 per_id[row['name']]=ids
 checks.append(row['name'])
(final/'per-id-counts.json').write_text(json.dumps(per_id,indent=2)+'\n')
guard=json.loads((final/'guard.json').read_text());cleanup=json.loads((final/'cleanup.json').read_text())
assert guard['exit']==0 and guard['violation'] is None and guard['servicesUnchanged'] and guard['minimumAvailable']>=15_000_000_000
assert cleanup['stateRemoved'] and cleanup['childrenRemaining']==0
assert not list(final.glob('private-state-*'))
late=[]
for delay in [1000,10000]:
 d=json.loads((final/f'late-{delay}.json').read_text());s=d['stats'];lost=[x for x in s['decryptions'] if not x['listener']]
 assert len(s['decryptions'])==1 and len(d['receipts'])==1 and len(lost)==1 and not s['messages'] and s['listener']
 assert len(s['requests'])>=2
 late.append({'delayMs':delay,'successfulDecryptions':len(s['decryptions']),'withoutListener':len(lost),'deliveredToApplication':len(s['messages']),'receipts':len(d['receipts']),'decryptions':s['decryptions']})
sources=json.loads((root/'sources-final/sources.json').read_text());nip=[x for x in sources if x['name'].endswith('-nip11')];assert len(nip)==3 and all('document' in x for x in nip)
machine=json.loads((root/'machine.json').read_text());integrity=json.loads((root/'integrity.json').read_text());assert integrity['checked']==80 and not integrity['mismatches']
burst_root=root/'burst';burst_data=json.loads((burst_root/'summary.json').read_text());assert burst_data['ok'];burst=burst_data['results'];assert len(burst)==4
assert {(r['n'],r['relays'],r['policy']) for r in burst}=={(2000,r,p) for r,p in itertools.product([1,3],['all-oldest','all-newest'])}
for r in burst:
 b=json.loads((burst_root/(r['name']+'.json')).read_text());s=b['stats'];seen={x['seq'] for x in s['validated']};assert r['droppedFrames']==len([x for x in s['frames'] if x['seq'] not in seen]);assert r['droppedFrames']>0
 assert r['droppedFrames']==(r['n']+1-1024)*r['relays'] and r['newCopies']==1
 assert r['droppedNew']==(r['relays'] if r['policy']=='all-oldest' else 0)
 assert s['elapsedMs']-max(x['ms'] for x in s['validated'])>1000
bg=json.loads((burst_root/'guard.json').read_text());bc=json.loads((burst_root/'cleanup.json').read_text());assert bg['exit']==0 and bg['servicesUnchanged'] and bg['minimumAvailable']>=15_000_000_000;assert bc['stateRemoved'] and bc['childrenRemaining']==0
compact={'burstDiagnostic':burst,'burstGuard':{k:v for k,v in bg.items() if k!='samples'},'burstCleanup':bc,'machine':machine,'integrity':integrity,'verified':True,'mainCases':len(main),'controlCases':1,'lateCases':len(late),'results':rows,'late':late,'guard':{k:v for k,v in guard.items() if k!='samples'},'cleanup':cleanup,'nip11':[{k:x.get(k) for k in ['name','url','fetchedUtc','limitations','retention','policyLinks']} for x in nip]}
pathlib.Path(a.summary).write_text(json.dumps(compact,indent=2)+'\n')
lines=['# Risultati: storia lunga e destinatario senza ascoltatore','', 'Prototipo separato, non destinato al merge. Misure su AI395; SDK `m3/integration` @ `3b314074` invariato, base prototipo `20e57c2eb5211fdf2de0c925dd800bb5593e1322`.','', '## Metodo e perimetro','',
'La storia è reale: 5.000 invii tramite SDK, crittografia MLS reale e relative 5.000 ricevute firmate. Ai checkpoint 100/500/1.000/2.000/5.000 si copiano gli stati MLS persistiti e cifrati di entrambi i membri. Ogni prova ripristina una copia separata dello stesso checkpoint: niente nuova identità o invito al riavvio. Le prove usano quattro scenari indipendenti concorrenti, tutti nello stesso lock; i tempi non sono un benchmark a macchina esclusiva.', '',
'Ogni relay conserva N eventi 4741 Alice→Bob più N ricevute 4742 Bob→Alice. Il filtro #p di Bob seleziona N messaggi, NON 2N frame: le ricevute sono indirizzate ad Alice. La storia è dello stesso gruppo; durante la generazione entrambi gli orologi applicativi hanno un offset coerente di −3.600.000 ms, già dall’avvio. Al riavvio gli orologi sono quelli reali: questo isola storia più vecchia del margine di 120 s da messaggi nuovi. Non rappresenta una storia tutta concentrata negli ultimi due minuti.', '',
'Il nuovo evento è prodotto e firmato dallo SDK di Alice prima dell’avvio di Bob, ma il relay ne trattiene pubblicazione e OK. Il primo REQ di Bob lo rende disponibile in tutti i relay durante start(); nella modalità oldest è collocato dopo la storia, nella modalità newest prima. È un caso sincronizzato di pubblicazione durante il riavvio, non un invio casuale sulla rete. Una sola nuova pubblicazione, maxAttempts=1: nessun reinvio del mittente può mascherare la perdita; il catch-up resta quello reale ogni 10 s.', '',
'Configurazione: perRelayTimeoutMs=12000 (default SDK), deadlineMs=60000, receiptMode=RECIPIENT_RECEIPT. start() attende sempre la fase di connessione di 12 s, anche sul loopback. Il primo catch-up periodico arriva quindi circa 22 s dopo il primo REQ, cioè circa 10 s dopo la risoluzione di start(). La finestra termina 12,5 s dopo start(): copre il primo catch-up. Nessuna conclusione di perdita permanente oltre questa finestra.', '',
'Osservazione della coda: unicamente nell’harness, JSON.parse aggiunge a ciascun frame un getter osservativo per sig, con le stesse sette chiavi e gli stessi valori. Il primo accesso avviene in receipts.validateEvent (righe 647–656), dopo l’estrazione dalla coda; non in catchUp.observe né nel trasporto. Il numero di sequenza distingue le copie del medesimo id. Frame arrivati al socket ma mai validati sono contati come cadute pre-validazione; si verifica inoltre che l’ultima validazione preceda lo snapshot di oltre 1 s. SDK, trasporto, crittografia e vendor non sono modificati. Un controllo aggiuntivo senza getter verifica il comportamento senza questa osservazione; non può misurare direttamente le cadute.', '',
'Wall time: dalla chiamata start() di Bob alla callback applicativa del nuovo messaggio. CPU: user+system del solo processo Bob, dall’inizio dell’harness membro (include ripristino MLS e osservazione); non CPU del relay o Alice. Le colonne frame EVENT ed errori riportano totale della finestra / numero fino alla consegna del nuovo. I file per caso conservano tutti gli identificativi, copie e tempi.','', f"Macchina: {machine['cpu']}, {machine['logicalCpus']} processori logici; Node {machine['node']}; {machine['platform']}. Integrità: {integrity['checked']} file protetti confrontati con il clone autorizzato, zero divergenze.",'', '## Matrice completa','',
'`all` = nessun tetto; `cap500` = massimo 500 risultati per filtro; `oldest` = ordine di generazione; `newest` = created_at decrescente, spareggio id decrescente. Il tetto agisce sui risultati storici di ciascun REQ, non sulla capacità totale né sulle notifiche live.','',
'| Storia N | Relay | Politica | Frame | E_SDK_SESSION_FAILED | Cadute storia / nuovo | Nuovo: copie | Tempo ms | CPU ms fino al nuovo |','|---:|---:|---|---:|---:|---:|---:|---:|---:|']
for r in sorted(main,key=lambda x:(x['n'],x['relays'],x['policy'])):
 m=r['message'];ms=f"{m['ms']-r['started']['startCallMs']:.1f}" if m else 'non consegnato';cpu=f"{(m['cpu']['user']+m['cpu']['system'])/1000:.1f}" if m else '—'
 lines.append(f"| {r['n']} | {r['relays']} | {r['policy']} | {r['frames']} / {m['wireFrames'] if m else '—'} | {r['sessionFailures']} / {m['sessionFailures'] if m else '—'} | {r['droppedHistorical']} / {r['droppedNew']} | {r['newCopies']} | {ms} | {cpu} |")
lines+=['','## Lettura dei risultati','',f"Casi principali: {len(main)}; consegna del nuovo nella finestra: {sum(x['delivered'] for x in main)}; casi con almeno una caduta del nuovo: {sum(x['droppedNew']>0 for x in main)}; casi con cadute storiche: {sum(x['droppedHistorical']>0 for x in main)}.", '',
'Una caduta riguarda un frame, non necessariamente l’identificativo definitivamente perduto: altre copie o il catch-up possono recuperarlo. Le ricevute e i duplicati passano comunque attraverso la validazione prima della deduplicazione. EOSE fa avanzare il cursore con l’orologio locale, non con l’esito delle elaborazioni. Queste misure mostrano il comportamento del caso qui costruito, non una garanzia generale di recupero dopo overflow, troncamento o retention.', '',
'### Controllo senza getter','']
for r in rows:
 if r['policy'].endswith('unobserved'):
  m=r['message'];lines.append(f"{r['name']}: frame={r['frames']}, errori sessione={r['sessionFailures']}, copie nuove={r['newCopies']}, tempo={(m['ms']-r['started']['startCallMs']) if m else None} ms. Nessuna misura di caduta pre-validazione in questo controllo.")
lines+=['','## Diagnosi separata della coda a 1.024','', 'Nella matrice WebSocket ordinaria non si osserva overflow: non basta sommare i frame dell’intera risposta per dedurre il picco di coda. Per verificare il limite in modo riproducibile, una seconda esecuzione genera 2.000 messaggi e ricevute reali. Solo nel suo adattatore socket trattiene i frame EVENT fino a EOSE, poi li inoltra tutti nello stesso turno JavaScript. Il contenuto e lo SDK rimangono invariati. Questa è una condizione di ingresso forzata, NON una misura della segmentazione TCP ordinaria né la prova che i relay pubblici si comportino così.', '', '| Relay | Ordine | Frame | Validati | Cadute storia / nuovo | Copie nuove | Tempo al nuovo ms |', '|---:|---|---:|---:|---:|---:|---:|']
for r in sorted(burst,key=lambda x:(x['relays'],x['policy'])):
 m=r['message'];lines.append(f"| {r['relays']} | {r['policy']} | {r['frames']} | {r['validated']} | {r['droppedHistorical']} / {r['droppedNew']} | {r['newCopies']} | {m['ms']-r['started']['startCallMs'] if m else 'non consegnato'} |")
lines+=['', 'Gli identificativi delle copie scartate sono in burst/n2000-r*-*.json, campo dropped, e quelli della matrice ordinaria sono anche aggregati in final2/per-id-counts.json. Cadute del nuovo seguite da consegna misurano recupero da altra copia o dal catch-up: non vanno chiamate perdita definitiva.', '', 'Comando della diagnosi (stesso guard e stesso lock):', '', '    EVIDENCE_DIR=/home/mverde/reviews/sdk-demo-2026-11/long-history-evidence/burst SIZES=2000 BURST_ONLY=1 DEMO_NODE=$HOME/.nvm/versions/node/v24.18.0/bin/node nice -n 19 ionice -c 3 python3 styx-js/demo/sdk-two-machines/long-history-guard.py', '', '## Nessuno in ascolto','', '| Listener dopo start() | Decifrati | Senza listener | Consegnati all’app dopo iscrizione | Ricevute firmate |','|---:|---:|---:|---:|---:|']
for x in late:lines.append(f"| {x['delayMs']} ms | {x['successfulDecryptions']} | {x['withoutListener']} | {x['deliveredToApplication']} | {x['receipts']} |")
lines+=['', 'Non è stato registrato un listener spia: non avrebbe più rappresentato “nessuno in ascolto”. Il conteggio usa open riuscito con plaintext valido, listener=false, e relativa ricevuta pubblicata; nel codice invariato receipts.js:966–971 l’emissione precede la ricevuta. client.js:1141–1158 fotografa l’audience presente in quel momento, senza replay per ascoltatori futuri. Le evidenze mostrano inoltre il ritorno del messaggio dal catch-up senza una successiva consegna applicativa. Questo è un messaggio perso per l’applicazione nonostante la ricevuta al mittente, non un errore di decifratura.', '',
'## Limiti dei relay: fonti primarie, sola lettura','',
'- strfry: [configurazione](https://github.com/hoytech/strfry/blob/master/strfry.conf), maxFilterLimit=500; [parser filtri](https://github.com/hoytech/strfry/blob/master/src/filters.h). Copie integrali ed ETag in sources-final/.','- nostr-rs-relay non ha genericamente un default 500: [SQLite](https://github.com/scsibug/nostr-rs-relay/blob/master/src/repo/sqlite.rs), righe 1149–1155, aggiunge LIMIT soltanto se f.limit è presente e altrimenti ordina ASC; [PostgreSQL](https://github.com/scsibug/nostr-rs-relay/blob/master/src/repo/postgres.rs), righe 891–899, applica invece ASC LIMIT 1000 senza limit. [Configurazione](https://github.com/scsibug/nostr-rs-relay/blob/master/config.toml). Pertanto la variante a 500 è un modello strfry, non una proprietà universale dei due server.','- NIP-11 distingue max_limit (tetto a limit esplicito) da default_limit (senza limit): [specifica](https://github.com/nostr-protocol/nips/blob/master/11.md). Nessun default_limit può essere dedotto automaticamente dal solo max_limit pubblicizzato.','',
'| Relay pubblico | max_limit | max_subscriptions | default_limit | retention |','|---|---:|---:|---|---|']
for x in nip:
 l=x['limitations'] or {};lines.append(f"| {x['name'].removesuffix('-nip11')} | {l.get('max_limit','non dichiarato')} | {l.get('max_subscriptions','non dichiarato')} | {l.get('default_limit','non dichiarato')} | {x['retention'] if x['retention'] is not None else 'non dichiarata'} |")
lines+=['','Acquisizione HTTPS con Accept: application/nostr+json; richieste aggiuntive alle sole pagine HTML dei relay. Nessun collegamento WebSocket pubblico né pubblicazione sintetica. Nei documenti e nelle pagine relay acquisite non risultano politiche di retention o link specifici a tali politiche; ciò non prova conservazione illimitata né l’assenza di altre politiche sul sito dell’operatore. Data, URL e intestazioni HTTP sono conservati in sources-final/sources.json.','',
'## Riproduzione e salvaguardie','',
'Comando effettivo da MVLINNA (coordinamento):','',
'    ssh AI395 \'cd /home/mverde/reviews/sdk-demo-2026-11/styx && EVIDENCE_DIR=/home/mverde/reviews/sdk-demo-2026-11/long-history-evidence/final2 DEMO_NODE=$HOME/.nvm/versions/node/v24.18.0/bin/node nice -n 19 ionice -c 3 python3 styx-js/demo/sdk-two-machines/long-history-guard.py\'','',
'Il guard acquisisce /home/mverde/reviews/styx-kanban/.ai395-test.lock per tutta la matrice, campiona MemAvailable ogni 2 s e confronta stato e PID di llama-swap, ds4-glm-full e ComfyUI senza modificarli. Tutti i figli ereditano nice 19 e ionice idle. Stato cifrato sintetico solo in una sottocartella privata temporanea delle evidenze, cancellata al termine e verificata assente. Nessuna chiave di stato o seed nei log.','',
f"Minimo RAM disponibile: {guard['minimumAvailable']} byte. Servizi invariati: {guard['servicesUnchanged']}. Stato eliminato: {cleanup['stateRemoved']}; figli residui: {cleanup['childrenRemaining']}.", '',
'Verifica/rendere report, sempre su AI395:','',
'    nice -n 19 ionice -c 3 python3 styx-js/demo/sdk-two-machines/long-history-report.py --evidence /home/mverde/reviews/sdk-demo-2026-11/long-history-evidence --report /home/mverde/reviews/sdk-demo-2026-11/RISULTATI-STORIA-LUNGA.IT.md --summary styx-js/demo/sdk-two-machines/LONG-HISTORY-SUMMARY.json','',
'## Fallimenti conservati e limiti','',
'pilot, pilot2, pilot3, pilot4: E_SDK_INVITE_TIMEOUT dell’harness perché deadline=30 s non copriva le fasi di connessione configurate a 30 s. pilot5: E_SDK_INVALID_CONFIG per timeout relay inferiore al minimo di 11 s. pilot6: FAILED_NO_RECEIPT generando eventi vecchi dopo avere arretrato un orologio già sincronizzato: i nuovi filtri since li escludevano. Corretto mantenendo l’offset storico coerente dall’avvio dei generatori. final: esecuzione interrotta esplicitamente per spostare lo stato temporaneo da /tmp al perimetro delle evidenze; rimozione verificata in manual-cleanup.json. Questi sono errori/limiti del banco prova, non risultati della matrice final2.', '',
'Una ripetizione per cella, più un controllo senza getter: nessuna distribuzione statistica o promessa di latenza di produzione. TCP loopback e risposte accorpate in burst favoriscono l’overflow; non sono un’emulazione della segmentazione di tutti i relay reali. Non viene dimostrata una perdita permanente in tutte le possibili condizioni di rete: si misura una finestra con un catch-up e una storia vecchia. Il tetto risultati può omettere messaggi senza riempire la coda; il caso con nuovo creato ora può essere recuperato dal since successivo, senza recuperare storia più vecchia eventualmente omessa. Nessun contratto M3 è stato cambiato, nessuna review LLM e nessun merge.','',
'Evidenze complete nel workspace: long-history-evidence/; solo dati sintetici, identificativi e misure, niente stato cifrato residuo. Il commit del prototipo contiene harness, questo rapporto e riepilogo verificato; le evidenze dettagliate sono conservate separatamente. Il riferimento di pubblicazione è registrato dopo il push nel file PUBBLICAZIONE-STORIA-LUNGA.json del workspace.','']
pathlib.Path(a.report).write_text('\n'.join(lines));print(json.dumps({'verified':True,'mainCases':len(main),'controlCases':1,'lateCases':2,'delivered':sum(x['delivered'] for x in main),'dropsNewCases':sum(x['droppedNew']>0 for x in main),'report':a.report}))
